CREATE COLUMN TABLE "TEST_AP"."ACRC" ("CreditCard" SMALLINT CS_INT NOT NULL , "CardName" NVARCHAR(30), "AcctCode" NVARCHAR(15), "Phone" NVARCHAR(20), "CompanyId" NVARCHAR(20), "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "UpdateDate" LONGDATE CS_LONGDATE, "IntTaxCode" NVARCHAR(2), "UserSign2" SMALLINT CS_INT, "Country" NVARCHAR(3), PRIMARY KEY ("CreditCard", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."ACRC" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$CardName$LogInstanc$','CardName','LogInstanc'));
CREATE INDEX "ACRC_CARD_NAME" ON "TEST_AP"."ACRC" ( "CardName" ASC, "LogInstanc" ASC )